def transform(grid):
    # What if only points with distance >= 4 along diagonal connect?
    res = [row[:] for row in grid]
    pts = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] != 0]
    for i in range(len(pts)):
        for j in range(len(pts)):
            r1, c1 = pts[i]
            r2, c2 = pts[j]
            if r2 - r1 == c2 - c1 and r2 - r1 >= 3:
                for k in range(1, r2 - r1):
                    res[r1+k][c1+k] = grid[r1][c1]
    return res
